// A node with a primary (left) and backup (right) approver.
public class ApproverNode {
    private final String role;
    private ApproverNode left;
    private ApproverNode right;

    public ApproverNode(String role) {
        this.role = role;
    }

    public String getRole() { return role; }
    public ApproverNode getLeft() { return left; }
    public ApproverNode getRight() { return right; }
    public void setLeft(ApproverNode left) { this.left = left; }
    public void setRight(ApproverNode right) { this.right = right; }
}
