package com.bank.dr;

import java.util.logging.Logger;

// Inverts an approver hierarchy for a disaster-recovery drill.
public class HierarchyInverterService {

    private static final Logger log = Logger.getLogger(HierarchyInverterService.class.getName());

    public ApproverNode invert(ApproverNode node) {
        // Base case: nothing to invert.
        if (node == null) {
            return null;
        }
        // Swap the primary and backup approvers at this node.
        ApproverNode temp = node.getLeft();
        node.setLeft(node.getRight());
        node.setRight(temp);

        // Recursively invert both subtrees.
        invert(node.getLeft());
        invert(node.getRight());
        return node;
    }

    public ApproverNode runDrill(ApproverNode root) {
        log.info("Running DR drill: inverting approver hierarchy (primary <-> backup)");
        ApproverNode inverted = invert(root);
        log.info("Inversion complete: backups are now primary at every level");
        return inverted;
    }

    // Pre-order traversal string for demonstration.
    public String preorder(ApproverNode node) {
        if (node == null) {
            return "_";
        }
        return node.getRole() + "(" + preorder(node.getLeft())
                + "," + preorder(node.getRight()) + ")";
    }
}
