package com.bank.dr;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class InvertTreeDemo {

    private static final Logger log = Logger.getLogger(InvertTreeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — DR Drill Hierarchy Inversion");

        // Build:        Manager
        //             /          \
        //      PrimaryCredit   BackupCredit
        //        /                   \
        //   PrimaryJr              BackupJr
        ApproverNode manager = new ApproverNode("Manager");
        ApproverNode primaryCredit = new ApproverNode("PrimaryCredit");
        ApproverNode backupCredit = new ApproverNode("BackupCredit");
        manager.setLeft(primaryCredit);
        manager.setRight(backupCredit);
        primaryCredit.setLeft(new ApproverNode("PrimaryJr"));
        backupCredit.setRight(new ApproverNode("BackupJr"));

        HierarchyInverterService service = new HierarchyInverterService();
        log.info("Before: " + service.preorder(manager));
        service.runDrill(manager);
        log.info("After:  " + service.preorder(manager));
    }
}
